/** Abstract base class for index allocators. */
abstract class IndexAllocator extends Module {
  val io = IO(new Bundle {
    /** Allocate an index.  valid indicates one is available; bits holds it.
      * ready from the consumer acknowledges the allocation (handshake). */
    val alloc = Decoupled(UInt(log2Ceil(capacity).W))
    /** Free a previously-allocated index.
      * valid indicates a free request; bits holds the index to release.
      * ready from the allocator (always true – free is never stalled). */
    val free  = Flipped(Valid(UInt(log2Ceil(capacity).W)))
  })

  def capacity: Int
}

/** A shifting-based free-list allocator.
  *
  * Maintains a queue of free indices.  On reset all indices 0..n-1 are
  * available in order.  The queue is implemented as a shift register so that
  * freed indices appear at the tail immediately (combinationally).
  *
  * Contract:
  *   - io.alloc.valid  – at least one free index exists
  *   - io.alloc.bits   – the index to be allocated (lowest available)
  *   - io.alloc.ready  – consumer asserts to take the index
  *   - io.free.valid   – producer asserts to return an index
  *   - io.free.bits    – the index being returned
  *   - io.free.ready   – not a real signal; always false (free is one-way)
  *
  * The "Out of order free" test expects the allocator to dole out freed
  * indices in FIFO order (the order they were freed).  The shifting
  * implementation below provides this property.
  */
class IndexAllocatorShifting(val capacity: Int) extends IndexAllocator {

  // Number of bits needed to represent a count 0..capacity
  private val cntBits = log2Ceil(capacity + 1)
  private val idxBits = log2Ceil(capacity)

  // -----------------------------------------------------------------
  // Storage: a Vec of entries and a count of how many are valid.
  // Entries are filled from the bottom; the oldest (lowest) index is
  // at position 0.
  // -----------------------------------------------------------------
  val entries = RegInit(VecInit((0 until capacity).map(_.U(idxBits.W))))
  val cnt     = RegInit(capacity.U(cntBits.W))

  // -----------------------------------------------------------------
  // Determine alloc / free events this cycle
  // -----------------------------------------------------------------
  val doAlloc = io.alloc.valid && io.alloc.ready
  val doFree  = io.free.valid

  // -----------------------------------------------------------------
  // Outputs (combinational)
  // -----------------------------------------------------------------
  io.alloc.valid := cnt > 0.U
  io.alloc.bits  := entries(0)  // always expose lowest entry

  // free.ready is not meaningful for a unidirectional free port
  // (defined as Flipped(Valid(...)) so there is no ready signal)

  // -----------------------------------------------------------------
  // Next-cycle state update
  // -----------------------------------------------------------------
  when(doAlloc && !doFree) {
    // Shift entries down by one, decrement count
    for (i <- 0 until capacity - 1) {
      entries(i) := entries(i + 1)
    }
    cnt := cnt - 1.U
  }.elsewhen(!doAlloc && doFree) {
    // Append freed index at tail (position cnt)
    entries(cnt) := io.free.bits
    cnt := cnt + 1.U
  }.elsewhen(doAlloc && doFree) {
    // Simultaneous alloc+free: shift down and insert at tail - 1
    // Net count stays the same.
    for (i <- 0 until capacity - 1) {
      entries(i) := entries(i + 1)
    }
    entries(cnt - 1.U) := io.free.bits
    // cnt unchanged
  }
}

