/** Generic synchronous FIFO using a circular buffer.
  *
  * @param gen   Data type of each element.
  * @param depth Number of entries in the FIFO (must be >= 1).
  */
class Fifo[T <: Data](gen: T, depth: Int) extends Module {
  require(depth >= 1, "FIFO depth must be at least 1")

  private val addrBits = log2Ceil(depth)
  private val cntBits  = log2Ceil(depth + 1)

  val io = IO(new Bundle {
    val enq   = Flipped(Decoupled(gen))
    val deq   = Decoupled(gen)
    val count = Output(UInt(cntBits.W))
  })

  val mem   = Mem(depth, gen)
  val head  = RegInit(0.U(addrBits.W))   // read pointer
  val tail  = RegInit(0.U(addrBits.W))   // write pointer
  val count = RegInit(0.U(cntBits.W))

  val full  = count === depth.U
  val empty = count === 0.U

  io.enq.ready := !full
  io.deq.valid := !empty
  io.deq.bits  := mem(head)
  io.count     := count

  when(io.enq.fire && !io.deq.fire) {
    mem(tail) := io.enq.bits
    tail      := Mux(tail === (depth - 1).U, 0.U, tail + 1.U)
    count     := count + 1.U
  }.elsewhen(!io.enq.fire && io.deq.fire) {
    head  := Mux(head === (depth - 1).U, 0.U, head + 1.U)
    count := count - 1.U
  }.elsewhen(io.enq.fire && io.deq.fire) {
    mem(tail) := io.enq.bits
    tail      := Mux(tail === (depth - 1).U, 0.U, tail + 1.U)
    head      := Mux(head === (depth - 1).U, 0.U, head + 1.U)
    // count unchanged
  }
}

