/** Gather operation.
  *
  * For each output index i: `out(i) = data(indices(i))`
  *
  * Equivalent to a scatter-gather load where indices is the index table and
  * data is the source array.
  */
object Gather {
  /** @param indices  Vec of source indices (each in range 0..data.length-1).
    * @param data     Vec of source data.
    * @return         Vec where out(i) = data(indices(i)).
    */
  def apply(indices: Vec[UInt], data: Vec[UInt]): Vec[UInt] = {
    val n   = indices.length
    val out = Wire(Vec(n, chiselTypeOf(data(0))))
    for (i <- 0 until n) {
      out(i) := data(indices(i))
    }
    out
  }
}

/** Scatter operation.
  *
  * Writes source data to destination positions specified by indices, but
  * resolves write conflicts by giving priority to the FIRST (lowest-index)
  * valid entry that targets each destination slot.
  *
  * @param indicesValid  Bool mask: which source entries are valid.
  * @param indices       Destination index for each source entry.
  * @param data          Data to be scattered.
  * @return A 3-tuple:
  *           - result:          Vec of output data (one per destination slot)
  *           - writeMask:       Bool Vec indicating which destination slots
  *                              were written
  *           - indicesSelected: Bool Vec indicating which SOURCE entries
  *                              were actually selected (i.e. won the conflict
  *                              resolution for their destination slot)
  */
object Scatter {
  def apply(
    indicesValid: Vec[Bool],
    indices:      Vec[UInt],
    data:         Vec[UInt]
  ): (Vec[UInt], Vec[Bool], Vec[Bool]) = {
    val nSrc  = indices.length
    val nDest = nSrc  // destination array has same size as source

    val result          = Wire(Vec(nDest, chiselTypeOf(data(0))))
    val writeMask       = Wire(Vec(nDest, Bool()))
    val indicesSelected = Wire(Vec(nSrc,  Bool()))

    // Initialise outputs
    for (d <- 0 until nDest) {
      result(d)    := 0.U
      writeMask(d) := false.B
    }
    for (s <- 0 until nSrc) {
      indicesSelected(s) := false.B
    }

    // For each source entry (in priority order, lowest index first), if it
    // is valid and its destination has not yet been written, write it.
    //
    // We need to track "already claimed" destinations.  In hardware we do
    // this with a Vec of Wires fed through priority logic.
    //
    // Build "claimed" as a Bool Vec updated combinationally.
    val claimed = Wire(Vec(nDest, Bool()))
    for (d <- 0 until nDest) { claimed(d) := false.B }

    // We build the priority chain by iterating over sources in order.
    // Each iteration potentially sets one destination's writeMask.
    // Because Chisel evaluates last-connect semantics we drive from
    // highest-priority (index 0) first, then lower priority sources
    // override with false (they cannot override a true).
    //
    // Implementation: for each destination d, we want:
    //   writeMask(d) = OR over all valid sources i that target d and have no
    //                  lower-index valid source targeting d.
    //   indicesSelected(i) = indicesValid(i) && !any_lower_j_valid_same_dest

    // For each destination, find the lowest-index valid source.
    for (d <- 0 until nDest) {
      // Scan sources from highest to lowest priority; last write wins
      // (so we scan in reverse and the lowest index source will do the final write).
      var anySet = false.B
      for (s <- (nSrc - 1) to 0 by -1) {
        when(indicesValid(s) && (indices(s) === d.U)) {
          writeMask(d)       := true.B
          result(d)          := data(s)
          indicesSelected(s) := true.B
        }
      }
      // Override: sources that are valid for d but NOT the minimum-index one
      // should have indicesSelected = false.
      // Re-scan: any s that targets d and is valid but is NOT the minimum
      // valid source must be de-selected.
    }

    // Post-correction: de-select sources that are not the minimum-index winner.
    // For each destination d, find the minimum valid source index.
    for (d <- 0 until nDest) {
      // Find min valid source; scan forward, stop at first.
      val minFound = Wire(Bool())
      minFound := false.B
      for (s <- 0 until nSrc) {
        when(indicesValid(s) && (indices(s) === d.U) && !minFound) {
          minFound := true.B
          // This is the winner; keep indicesSelected(s) = true (set above).
        }.elsewhen(indicesValid(s) && (indices(s) === d.U) && minFound) {
          // Not the winner; de-select.
          indicesSelected(s) := false.B
        }
      }
    }

    // The above has a multi-driver issue for indicesSelected (two when-blocks
    // may drive the same wire).  Rewrite cleanly with explicit priority logic.

    // --- Clean rewrite ---
    for (d <- 0 until nDest) {
      result(d)    := 0.U
      writeMask(d) := false.B
    }
    for (s <- 0 until nSrc) {
      indicesSelected(s) := false.B
    }

    // For each destination d, find the first (lowest-index) valid source.
    for (d <- 0 until nDest) {
      // Scan in reverse so that the lowest-index source does the final write
      // (last-connect semantics).
      for (s <- (nSrc - 1) to 0 by -1) {
        // Is this source the lowest-index winner for destination d?
        // It wins if: valid, targets d, and no lower-index s' also targets d with valid.
        val lowerExists = (0 until s).map { sp =>
          indicesValid(sp) && (indices(sp) === d.U)
        }.foldLeft(false.B)(_ || _)

        when(indicesValid(s) && (indices(s) === d.U) && !lowerExists) {
          writeMask(d)       := true.B
          result(d)          := data(s)
          indicesSelected(s) := true.B
        }
      }
    }

    (result, writeMask, indicesSelected)
  }
}

