import chisel3._
import chisel3.util._

// ---------------------------------------------------------------------------
// FMA pipeline stage bundles
// ---------------------------------------------------------------------------

/** Input command to the FMA pipeline. */
class FmaCmd extends Bundle {
  val ina = new Fp32
  val inb = new Fp32
  val inc = new Fp32
}

/** Intermediate state after FMA stage 1 (multiply). */
class FmaState1 extends Bundle {
  // Sign of the product a*b
  val prodSign      = UInt(1.W)
  // Unbiased exponent of the product: exp_a + exp_b - 127 (can be signed)
  val prodExp       = SInt(10.W)
  // 48-bit product mantissa (1.man_a * 1.man_b), kept full precision
  val prodMantissa  = UInt(48.W)
  // Pass-through of the addend c
  val inc           = new Fp32
  // Pass-through flags
  val prodIsNan     = Bool()
  val prodIsInf     = Bool()
  val prodIsZero    = Bool()
}

/** Intermediate state after FMA stage 2 (align + add). */
class FmaState2 extends Bundle {
  // Sum sign
  val sumSign       = UInt(1.W)
  // Biased exponent of the normalised result (pre-rounding)
  val sumExp        = UInt(8.W)
  // 25-bit unnormalised sum mantissa (2 guard bits retained)
  val sumMantissa   = UInt(25.W)
  // Special-case flags
  val isNan         = Bool()
  val isInf         = Bool()
  val isZero        = Bool()
}

// ---------------------------------------------------------------------------
// FMA implementation
// ---------------------------------------------------------------------------

/** Fused Multiply-Add for IEEE 754 single-precision floats.
  *
  * Computes result = (ina * inb) + inc using a 3-stage pipeline.
  * The stages are exposed as pure functions (no registers) so callers can
  * either use them combinationally or insert pipeline registers between them.
  *
  * Stage 1: multiply ina * inb
  * Stage 2: align and add the product with inc
  * Stage 3: normalise and round to produce the final Fp32
  */
object Fma {

  // -------------------------------------------------------------------------
  // Stage 1: multiply
  // -------------------------------------------------------------------------
  def FmaStage1(cmd: FmaCmd): FmaState1 = {
    val s = Wire(new FmaState1)

    val a = cmd.ina
    val b = cmd.inb

    // --- Product sign ---
    s.prodSign := a.sign ^ b.sign

    // --- Product exponent (unbiased: subtract bias 127 once) ---
    // bias = 127; biased_exp = exp_a + exp_b - 127
    // Use SInt arithmetic to handle underflow.
    val expA = a.exponent.zext  // 9-bit SInt
    val expB = b.exponent.zext
    s.prodExp := (expA + expB - 127.S)(9, 0).asSInt

    // --- Product mantissa: (1.man_a) * (1.man_b) → 48-bit result ---
    // Implicit leading 1 only for normal numbers (exponent != 0).
    val manA = Mux(a.exponent =/= 0.U,
                   Cat(1.U(1.W), a.mantissa),   // 24-bit: 1.mantissa
                   Cat(0.U(1.W), a.mantissa))
    val manB = Mux(b.exponent =/= 0.U,
                   Cat(1.U(1.W), b.mantissa),
                   Cat(0.U(1.W), b.mantissa))
    s.prodMantissa := (manA * manB)(47, 0)

    // --- Special-case detection ---
    s.prodIsNan  := a.isNan() || b.isNan() || (a.isInf() && b.isZero()) || (a.isZero() && b.isInf())
    s.prodIsInf  := (a.isInf() || b.isInf()) && !s.prodIsNan
    s.prodIsZero := (a.isZero() || b.isZero()) && !s.prodIsInf && !s.prodIsNan

    s.inc := cmd.inc
    s
  }

  // -------------------------------------------------------------------------
  // Stage 2: align addend and add
  // -------------------------------------------------------------------------
  def FmaStage2(s1: FmaState1): FmaState2 = {
    val s = Wire(new FmaState2)

    val c = s1.inc

    // --- Handle special cases early ---
    val anyNan = s1.prodIsNan || c.isNan()
    val anyInf = s1.prodIsInf || c.isInf()

    // Infinity sign: if both are inf with different signs → NaN (for add).
    // For simplicity, signal NaN when inf-inf cancellation.
    val infSign = Mux(s1.prodIsInf && c.isInf() && (s1.prodSign =/= c.sign),
                      true.B, false.B)  // inf - inf = NaN
    val resultNan = anyNan || infSign

    // --- Product exponent as biased ---
    // s1.prodExp is unbiased (could be negative).  Add bias back.
    // The product's biased exponent = s1.prodExp + 127.
    // Detect overflow/underflow.
    val prodBiasedExp = s1.prodExp + 127.S  // 10-bit SInt

    // Determine which operand has the larger exponent.
    // Product mantissa: 48 bits, with the implicit 1 at bit 47 (if normalised)
    // or bit 46 (if the product had leading zeros).
    // For alignment we treat the product mantissa as a 24-bit 1.frac value
    // shifted left by 24 (i.e. mantissa(47:24) is the integer part).
    // We use the high 24 bits and work at 24-bit precision + guard bits.

    // Represent the product as a signed 27-bit value (24 + 3 guard bits)
    // at the product's exponent.
    // For the addend c, represent it the same way at c's exponent.

    // Determine the effective exponent and mantissa for both operands.
    // Product: biased exponent = prodBiasedExp.  If the 47th bit of
    // prodMantissa is set, the product is >= 2 and the exponent is
    // prodBiasedExp; otherwise the product is in [1,2) if bit 46 is set,
    // with exponent prodBiasedExp - 1, etc.
    // To keep things tractable we normalise the product first.

    // Find leading bit position of the 48-bit product.
    val prodLeadBit = Wire(UInt(6.W))
    prodLeadBit := 0.U
    for (k <- 0 until 48) {
      when(s1.prodMantissa(k)) {
        prodLeadBit := k.U
      }
    }
    // Normalised product biased exponent = prodBiasedExp - (47 - prodLeadBit)
    // i.e. adjust so that the implicit 1 is at bit 47.
    val prodNormExp = prodBiasedExp - (47.S - prodLeadBit.zext)

    // Product 24-bit mantissa (implicit 1 included): shift so leading 1 is at bit 23.
    val prodShiftAmt = Wire(UInt(6.W))
    prodShiftAmt := Mux(47.U >= prodLeadBit, 47.U - prodLeadBit, 0.U)
    val prodMantNorm = (s1.prodMantissa << prodShiftAmt)(47, 24)  // top 24 bits

    // Addend c 24-bit mantissa (implicit 1 included).
    val cMant24 = Mux(c.exponent =/= 0.U,
                      Cat(1.U(1.W), c.mantissa),
                      Cat(0.U(1.W), c.mantissa))

    // We now need to align cMant24 with prodMantNorm.
    // Let E_p = prodNormExp, E_c = c.exponent.
    // If E_p > E_c: shift c right by (E_p - E_c).
    // If E_c > E_p: shift prod right by (E_c - E_p).
    // We work with 25-bit accumulators (1 overflow bit + 24 mantissa bits)
    // extended to 27 bits to keep 2 guard/round bits.

    val expP = prodNormExp  // SInt
    val expC = c.exponent.zext  // SInt

    val prodMant27 = Cat(0.U(3.W), prodMantNorm)  // 27 bits: [0 | 0.0 | prod24]
    // Actually place implicit 1 at bit 24:
    // prodMant27 = 27-bit value with the 1.frac at bits 24 downto 1, plus guard at 0.
    val prodMantAligned = Cat(0.U(2.W), prodMantNorm, 0.U(1.W))  // 27 bits

    val cMant27Aligned = Cat(0.U(2.W), cMant24, 0.U(1.W))  // 27 bits

    // Shift amounts (clamp to 27 to avoid over-shift)
    val expDiff = expP - expC  // SInt
    val shiftC   = Mux(expDiff  > 0.S, expDiff.asUInt,  0.U)(5, 0)
    val shiftP   = Mux(expDiff  < 0.S, (-expDiff).asUInt, 0.U)(5, 0)

    val maxShift = 27.U
    val cShifted = Mux(shiftC > maxShift, 0.U, (cMant27Aligned >> shiftC)(26, 0))
    val pShifted = Mux(shiftP > maxShift, 0.U, (prodMantAligned >> shiftP)(26, 0))

    val resultExp = Mux(expDiff >= 0.S, expP, expC)

    // Signed addition with sign-magnitude conversion.
    // prodSign and c.sign determine whether we add or subtract.
    val prodVal = pShifted.zext  // 28-bit SInt
    val cVal    = cShifted.zext

    val prodSigned = Mux(s1.prodSign.asBool, -prodVal, prodVal)
    val cSigned    = Mux(c.sign.asBool,      -cVal,    cVal)
    val sumSigned  = prodSigned + cSigned  // 28-bit SInt

    val sumNeg  = sumSigned < 0.S
    val sumAbs  = Mux(sumNeg, (-sumSigned)(26, 0), sumSigned(26, 0))

    s.sumSign := Mux(resultNan || anyNan,      0.U,
                 Mux(s1.prodIsZero && !c.isZero(), c.sign,
                 Mux(!s1.prodIsZero && c.isZero(), s1.prodSign,
                 Mux(sumNeg, 1.U, 0.U))))

    // Clamp resultExp to UInt(8.W) range
    val resultExpU = Mux(resultExp <= 0.S, 0.U,
                     Mux(resultExp >= 254.S, 254.U,
                         resultExp.asUInt(7, 0)))
    s.sumExp      := resultExpU
    s.sumMantissa := sumAbs(24, 0)
    s.isNan       := resultNan
    s.isInf       := anyInf && !resultNan
    s.isZero      := !resultNan && !anyInf && (sumAbs === 0.U) && s1.prodIsZero && c.isZero()
    s
  }

  // -------------------------------------------------------------------------
  // Stage 3: normalise and round
  // -------------------------------------------------------------------------
  def FmaStage3(s2: FmaState2): Fp32 = {
    val fp = Wire(new Fp32)

    when(s2.isNan) {
      fp.sign     := 0.U
      fp.exponent := 0xFF.U
      fp.mantissa := 1.U  // quiet NaN
    }.elsewhen(s2.isInf) {
      fp.sign     := s2.sumSign
      fp.exponent := 0xFF.U
      fp.mantissa := 0.U
    }.elsewhen(s2.isZero) {
      fp.sign     := 0.U
      fp.exponent := 0.U
      fp.mantissa := 0.U
    }.otherwise {
      // Normalise: find the leading 1 in sumMantissa (25 bits)
      val mant = s2.sumMantissa  // 25 bits

      // Find leading bit position
      val leadPos = Wire(UInt(5.W))
      leadPos := 0.U
      for (k <- 0 until 25) {
        when(mant(k)) {
          leadPos := k.U
        }
      }

      // We want the implicit 1 at bit 23 of the final mantissa.
      // sumMantissa is a 25-bit value; the integer part is at bits 24:23.
      // Normalise so that the leading 1 is at position 23.
      val shiftNeeded = Wire(SInt(6.W))
      shiftNeeded := 23.S - leadPos.zext

      val shifted = Wire(UInt(25.W))
      when(shiftNeeded >= 0.S) {
        shifted := (mant << shiftNeeded.asUInt)(24, 0)
      }.otherwise {
        shifted := (mant >> (-shiftNeeded).asUInt)(24, 0)
      }

      val mantissa23 = shifted(22, 0)

      // Adjust exponent by the normalisation shift.
      val adjExp = s2.sumExp.zext - shiftNeeded  // SInt arithmetic

      // Handle underflow → zero; overflow → inf
      when(adjExp <= 0.S || leadPos === 0.U) {
        fp.sign     := 0.U
        fp.exponent := 0.U
        fp.mantissa := 0.U
      }.elsewhen(adjExp >= 255.S) {
        fp.sign     := s2.sumSign
        fp.exponent := 0xFF.U
        fp.mantissa := 0.U
      }.otherwise {
        fp.sign     := s2.sumSign
        fp.exponent := adjExp.asUInt(7, 0)
        fp.mantissa := mantissa23
      }
    }

    fp
  }
}

/** Top-level Fma module (for use when a Module wrapper is required). */
class Fma extends Module {
  val io = IO(new Bundle {
    val cmd = Input(new FmaCmd)
    val out = Output(new Fp32)
  })

  val s1 = Fma.FmaStage1(io.cmd)
  val s2 = Fma.FmaStage2(s1)
  io.out := Fma.FmaStage3(s2)
}

