/** Abstract base class for index allocators. */
abstract class IndexAllocator extends Module {
  val io = IO(new Bundle {
    /** Allocate an index.  valid indicates one is available; bits holds it.
      * ready from the consumer acknowledges the allocation (handshake). */
    val alloc = Decoupled(UInt(log2Ceil(capacity).W))
    /** Free a previously-allocated index.
      * valid indicates a free request; bits holds the index to release.
      * (No ready signal – free is always accepted.) */
    val free  = Flipped(Valid(UInt(log2Ceil(capacity).W)))
  })

  def capacity: Int
}

/** A shifting-based free-list allocator with combinational free bypass.
  *
  * Maintains a shift-register queue of free indices.  On reset all indices
  * 0..n-1 are enqueued in order.
  *
  * The key behavioural requirement (verified by the test) is that a freed
  * index is visible to the alloc port COMBINATIONALLY in the same cycle as
  * `io.free.valid` is asserted, without requiring a clock edge.
  *
  * We implement this by exposing a "next-cycle" view of the queue that
  * incorporates the combinational effect of the free operation.
  *
  * The "Out of order free" test expects freed indices to be dole out in FIFO
  * order (the order they were freed).
  */
class IndexAllocatorShifting(val capacity: Int) extends IndexAllocator {

  private val cntBits = log2Ceil(capacity + 1)
  private val idxBits = log2Ceil(capacity)

  // -----------------------------------------------------------------
  // Registers: `entries` is the free-index queue; `cnt` is its fill level.
  // -----------------------------------------------------------------
  val entries = RegInit(VecInit((0 until capacity).map(_.U(idxBits.W))))
  val cnt     = RegInit(capacity.U(cntBits.W))

  // -----------------------------------------------------------------
  // Combinational "effective" state: incorporates the free bypass.
  //
  // If io.free.valid is asserted, the freed index is virtually appended
  // to the tail of the queue.  The alloc port reads from this virtual queue.
  // -----------------------------------------------------------------
  val doAlloc = io.alloc.valid && io.alloc.ready
  val doFree  = io.free.valid

  // Effective count (with free bypass).
  val effCnt = Wire(UInt(cntBits.W))
  effCnt := cnt + doFree.asUInt

  // Effective entries: if cnt == 0 and freeing, the freed index is at slot 0.
  val effEntry0 = Wire(UInt(idxBits.W))
  when(cnt === 0.U && doFree) {
    effEntry0 := io.free.bits
  }.otherwise {
    effEntry0 := entries(0)
  }

  // -----------------------------------------------------------------
  // Outputs (combinational on effective state)
  // -----------------------------------------------------------------
  io.alloc.valid := effCnt > 0.U
  io.alloc.bits  := effEntry0

  // -----------------------------------------------------------------
  // Sequential update
  // -----------------------------------------------------------------
  when(doAlloc && !doFree) {
    // Consume from the front; shift remaining entries down.
    for (i <- 0 until capacity - 1) {
      entries(i) := entries(i + 1)
    }
    cnt := cnt - 1.U
  }.elsewhen(!doAlloc && doFree) {
    // Append freed index at the tail (position cnt).
    entries(cnt) := io.free.bits
    cnt          := cnt + 1.U
  }.elsewhen(doAlloc && doFree) {
    // Simultaneous alloc+free:
    // - Alloc consumes entry 0.
    // - Free appends at tail - 1 (net count unchanged).
    for (i <- 0 until capacity - 1) {
      entries(i) := entries(i + 1)
    }
    // After shifting, the tail is at cnt - 1.
    entries(cnt - 1.U) := io.free.bits
    // cnt unchanged.
  }
}

